<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Order; use Illuminate\Http\Request; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException;
class AdminOrderController extends Controller { private const STATUSES=['pending_payment','paid','processing','packed','shipped','completed','cancelled','expired','refunded']; public function index(Request $r) { $d=$r->validate(['status'=>['nullable',Rule::in(self::STATUSES)],'search'=>['nullable','string','max:100']]); $q=Order::with('items')->latest(); if($d['status']??null)$q->where('status',$d['status']); if($d['search']??null)$q->where('number','like','%'.$d['search'].'%'); return response()->json($q->paginate(20)); } public function show(Order $order) { return response()->json(['data'=>$order->load(['items','histories'])]); } public function updateStatus(Request $r, Order $order) { $d=$r->validate(['status'=>['required',Rule::in(self::STATUSES)],'note'=>['nullable','string','max:1000']]); if($order->status===$d['status']) throw ValidationException::withMessages(['status'=>['Status order tidak berubah.']]); $order->update(['status'=>$d['status']]); $order->histories()->create(['status'=>$d['status'],'note'=>$d['note']??null]); return response()->json(['data'=>$order->load('histories')]); } }
